    skillChoices: ['animal-handling', 'arcana', 'insight', 'medicine', 'nature', 'perception', 'religion', 'survival'],
    numSkillChoices: 2,
    startingEquipment: ['Leather Armor', 'Shield', 'Sickle', 'Druidic Focus (Quarterstaff)', 'Explorer’s Pack', 'Herbalism Kit', '9 GP'],
    subclassLevel: 3,
